import AWS from "aws-sdk";
export default {
  props: {
    viewProfilePic: Boolean,
    rowInfoData: Object
  },
  data() {
    return {
      presignedUrl: ""
    };
  },
  watch: {
    viewProfilePic: {
      async handler() {
        if (this.viewProfilePic == true) {}
      },
      immediate: true
    }
  },
  methods: {
    close_dialog() {
      this.$emit("clicked", 0);
    },
    checkImageExtension(value) {
      return value.endsWith(".img") || value.endsWith(".png") || value.endsWith(".jpeg") || value.endsWith(".jpg");
    },
    getImageSrc(val) {
      var data = this.$store.getters.GetOrgDetails;
      const s3 = new AWS.S3({
        region: data.s3_details.region,
        accessKeyId: data.s3_details.access_key,
        secretAccessKey: data.s3_details.secret_key
      });
      const params = {
        Bucket: data.s3_details.bucket_name,
        Key: "workflow/" + this.rowInfoData.respectiveValue.split("workflow/")[1],
        Expires: 604800
      };
      const presignedUrl = s3.getSignedUrl("getObject", params);
      if (val == "image") {
        return presignedUrl;
      } else {
        window.open(presignedUrl, "_blank");
      }
    },
    get_value(value) {
      const name = value.substring(value.lastIndexOf("/") + 1);
      return name.split("__")[1];
    }
  }
};
